package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class DecimalWholeProductsTest {
 @Test public void fullSelectedDomainHasExactValuesIncludingZeroAndWholeBoundaries(){int count=0;for(int a=0;a<=999;a++)for(int b=0;b<=99;b++){Question q=DecimalWholeProducts.make(a,b);assertEquals(Rational.of((long)a*b,100),Expression.number(q.answers[0]));assertTrue(new Checker().check(q,List.of(),List.of(q.answers[0])).correct());count++;}assertEquals(100000,count);assertEquals("0",DecimalWholeProducts.make(0,99).answers[0]);assertEquals("0",DecimalWholeProducts.make(999,0).answers[0]);assertEquals("989.01",DecimalWholeProducts.make(999,99).answers[0]);}
 @Test public void sixBlankFramesAndHiddenAnswerIndependence(){Question q=new Question("decimalMul","3.75 × 24","poison","999");HelpPlan h=HelpPlan.forQuestion(q);assertEquals(6,h.size());assertFalse(h.canTransfer());List<String> v=List.of("3.75","24","2","375","9000","90");for(int i=0;i<v.size();i++){assertTrue(h.step(i).accepts(v.get(i)));assertFalse(h.step(i).accepts(""));}assertFalse(h.step(4).accepts("9001"));}
 @Test public void selectedYearSixSupplyIsFreshAndUnreviewedPowerTypesStayOutOfFallback(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade("decimalMul",6));var limits=GlobalCurriculum.limits(pack.id,"decimalMul",6);assertTrue(DecimalWholeProducts.supports("decimalMul",limits));assertFalse(DecimalWholeProducts.supports("decimalMul",CurriculumLimits.NONE));Generator g=new Generator(new Random(93));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next("decimalMul",recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertTrue(limits.allows(q));assertEquals(6,HelpPlan.forQuestion(q).size());}Learning.Profile p=new Learning.Profile();p.countryCode="KR";p.educationSystem="kr-national";assertTrue(GlobalCurriculum.available(p).stream().noneMatch(x->DecimalPowerTen.supports(x.id)));assertTrue(pack.inGrade(DecimalPowerTen.MUL,6));}
}
